package com.quincaisoft.workers.application;
import com.quincaisoft.workers.api.*;import com.quincaisoft.identity.api.*;import com.quincaisoft.audit.api.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;
/** Named informational consumer. It never repeats an economic source operation. */
@Service public class DefaultOutboxWorker implements OutboxWorker {
private final EntityManager em;private final ScopedTransactions tx;private final AuditService audit;private final IdentityService identity;
public DefaultOutboxWorker(EntityManager em,ScopedTransactions tx,AuditService audit,IdentityService identity){this.em=em;this.tx=tx;this.audit=audit;this.identity=identity;}
private record Lease(UUID event,long token,String owner){}
public Result projectAudit(int limit){if(limit<1||limit>100)throw new IllegalArgumentException("Limit must be 1–100");identity.members();int processed=0,failed=0;for(int i=0;i<limit;i++){var lease=claim();if(lease==null)break;try{complete(lease);processed++;}catch(RuntimeException failure){retry(lease);failed++;}}return new Result(processed,failed);}
private Lease claim(){return tx.execute(()->{var s=TenantContext.current();String owner=UUID.randomUUID().toString();em.createNativeQuery("insert into outbox_delivery(tenant_id,event_id,consumer_name) select tenant_id,id,'audit-projection-v1' from outbox_event on conflict do nothing").executeUpdate();var rows=em.createNativeQuery("select event_id from outbox_delivery where consumer_name='audit-projection-v1' and completed_at is null and next_retry_at<=now() and (lease_expires_at is null or lease_expires_at<now()) order by next_retry_at,event_id for update skip locked limit 1").getResultList();if(rows.isEmpty())return null;UUID event=(UUID)rows.getFirst();Number token=(Number)em.createNativeQuery("update outbox_delivery set lease_owner=:o,fencing_token=fencing_token+1,lease_expires_at=now()+interval '30 seconds',attempt=attempt+1 where tenant_id=:t and event_id=:e and consumer_name='audit-projection-v1' returning fencing_token").setParameter("o",owner).setParameter("t",s.tenantId()).setParameter("e",event).getSingleResult();return new Lease(event,token.longValue(),owner);});}
private void complete(Lease l){tx.execute(()->{var s=TenantContext.current();var valid=em.createNativeQuery("select event_id from outbox_delivery where tenant_id=:t and event_id=:e and consumer_name='audit-projection-v1' and lease_owner=:o and fencing_token=:f and lease_expires_at>now() and completed_at is null for update").setParameter("t",s.tenantId()).setParameter("e",l.event).setParameter("o",l.owner).setParameter("f",l.token).getResultList();if(valid.isEmpty())throw new IllegalStateException("Stale worker lease");int inserted=em.createNativeQuery("insert into inbox_receipt(tenant_id,consumer_name,event_id) values(:t,'audit-projection-v1',:e) on conflict do nothing").setParameter("t",s.tenantId()).setParameter("e",l.event).executeUpdate();if(inserted==1){Object[] event=(Object[])em.createNativeQuery("select event_type,aggregate_type,aggregate_id from outbox_event where tenant_id=:t and id=:e").setParameter("t",s.tenantId()).setParameter("e",l.event).getSingleResult();audit.append(l.event,"OutboxProjected",(String)event[1],(UUID)event[2],"Committed informational event: "+event[0]);}em.flush();em.createNativeQuery("update outbox_delivery set completed_at=now(),lease_expires_at=null where tenant_id=:t and event_id=:e and consumer_name='audit-projection-v1' and lease_owner=:o and fencing_token=:f").setParameter("t",s.tenantId()).setParameter("e",l.event).setParameter("o",l.owner).setParameter("f",l.token).executeUpdate();return null;});}
private void retry(Lease l){tx.execute(()->{var s=TenantContext.current();em.createNativeQuery("update outbox_delivery set lease_expires_at=null,next_retry_at=now()+interval '60 seconds' where tenant_id=:t and event_id=:e and consumer_name='audit-projection-v1' and lease_owner=:o and fencing_token=:f and completed_at is null").setParameter("t",s.tenantId()).setParameter("e",l.event).setParameter("o",l.owner).setParameter("f",l.token).executeUpdate();return null;});}
}